	hctx := HookContext{
		Event:    HookAgentToolCodeEditEnded,
		Client:   "claude-code",
		Second:   "2026-03-16T12:00:00Z",
		RepoRoot: tmpDir,
		Input:    payload,
	}
	result := dispatchHook(hctx)
